import type { GeospatialCamera } from "@babylonjs/lite";

export function centerOnLatLon(camera: GeospatialCamera, latitudeDeg: number, longitudeDeg: number): void {
  const lat = (latitudeDeg * Math.PI) / 180;
  const lon = (longitudeDeg * Math.PI) / 180;
  const r = camera.limits.planetRadius;
  const cosLat = Math.cos(lat);

  camera.center = {
    x: r * cosLat * Math.cos(lon),
    y: -r * cosLat * Math.sin(lon),
    z: r * Math.sin(lat),
  };
}
```

I added `src/center-on.ts`, which assigns a new `center` vector on the camera’s planet-radius sphere using +Z as north and -Y as east so that yaw 90° points toward positive longitude. I inferred the coordinate sign from the notes; I was not sure whether the runtime `Vec3` type is a plain object or a class with extra methods, but the provided declarations only expose `x`, `y`, and `z`.
